import React, { useState, useEffect } from 'react';
import api from './api';

const G = {
  bg:'#0A0A0A', card:'#111111', card2:'#181818', border:'#1E1E1E', border2:'#252525',
  green:'#22C55E', greenDark:'#16A34A', greenBg:'#052E1C', greenBdr:'#166534',
  text:'#EEEEEE', text2:'#888888', text3:'#444444',
  red:'#EF4444', amber:'#F59E0B', purple:'#818CF8',
};

const css = {
  app:       { minHeight:'100vh', background:G.bg, color:G.text, fontFamily:"'Inter',sans-serif", fontSize:14 },
  center:    { display:'flex', alignItems:'center', justifyContent:'center', minHeight:'100vh', padding:16 },
  col:       { display:'flex', flexDirection:'column', gap:12 },
  row:       { display:'flex', alignItems:'center', gap:8 },
  card:      { background:G.card, border:`1px solid ${G.border}`, borderRadius:16, padding:20 },
  card2:     { background:G.card2, border:`1px solid ${G.border2}`, borderRadius:12, padding:16 },
  authWrap:  { width:'100%', maxWidth:400 },
  brand:     { textAlign:'center', marginBottom:32 },
  brandIcon: { width:72, height:72, borderRadius:20, background:G.greenBg, display:'flex', alignItems:'center', justifyContent:'center', fontSize:32, margin:'0 auto 16px', border:`1px solid ${G.greenBdr}` },
  brandName: { fontSize:32, fontWeight:900, color:G.green, letterSpacing:0.5 },
  brandSub:  { fontSize:13, color:G.text3, marginTop:6 },
  formTitle: { fontSize:22, fontWeight:800, color:G.text, marginBottom:20 },
  label:     { fontSize:11, fontWeight:700, color:G.text3, textTransform:'uppercase', letterSpacing:0.8, marginBottom:6, display:'block' },
  input:     { width:'100%', background:G.card2, border:`1px solid ${G.border2}`, borderRadius:10, padding:'13px 14px', fontSize:15, color:G.text, outline:'none', boxSizing:'border-box' },
  btn:       { width:'100%', background:G.greenDark, color:'#fff', border:'none', borderRadius:10, padding:'15px 20px', fontSize:16, fontWeight:700, cursor:'pointer' },
  btnSm:     { background:G.greenDark, color:'#fff', border:'none', borderRadius:8, padding:'10px 18px', fontSize:13, fontWeight:600, cursor:'pointer' },
  link:      { color:G.green, cursor:'pointer', fontWeight:600 },
  linkText:  { fontSize:13, color:G.text3, textAlign:'center' },
  err:       { background:'#200A0A', border:'1px solid #450A0A', borderRadius:8, padding:'10px 14px', fontSize:13, color:G.red },
  ok:        { background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:8, padding:'10px 14px', fontSize:13, color:G.green },
  nav:       { background:'#0F0F0F', borderBottom:`1px solid ${G.border}`, padding:'0 20px', display:'flex', alignItems:'center', justifyContent:'space-between', height:56, position:'sticky', top:0, zIndex:100 },
  navBrand:  { fontSize:20, fontWeight:900, color:G.green },
  tabBar:    { position:'fixed', bottom:0, left:0, right:0, background:'#0F0F0F', borderTop:`1px solid ${G.border}`, display:'flex', zIndex:100 },
  tabItem:   { flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'10px 0', cursor:'pointer', fontSize:10, fontWeight:600, gap:4 },
  page:      { maxWidth:480, margin:'0 auto', padding:'20px 16px 90px' },
  pageTitle: { fontSize:26, fontWeight:800, color:G.text, marginBottom:20 },
  sectionLabel: { fontSize:11, fontWeight:700, color:G.text3, textTransform:'uppercase', letterSpacing:0.8, marginBottom:10, display:'block' },
  badge:     { borderRadius:20, padding:'3px 10px', fontSize:10, fontWeight:700, display:'inline-block' },
};

const STATUS_STYLE = {
  pending_payment: { bg:'#2D1F00', color:G.amber,  label:'Awaiting payment' },
  queued:          { bg:'#1A1040', color:G.purple, label:'In queue' },
  printing:        { bg:G.greenBg, color:G.green,  label:'Printing' },
  ready:           { bg:G.greenBg, color:G.green,  label:'Ready for pickup' },
  collected:       { bg:'#1A1A1A', color:G.text3,  label:'Collected' },
  cancelled:       { bg:'#200A0A', color:G.red,    label:'Cancelled' },
  failed:          { bg:'#200A0A', color:G.red,    label:'Failed' },
};

function Spinner() {
  return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', padding:40 }}>
      <div style={{ width:32, height:32, border:`3px solid ${G.border}`, borderTop:`3px solid ${G.green}`, borderRadius:'50%', animation:'spin 0.8s linear infinite' }}/>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

function Alert({ msg, type='error' }) {
  if (!msg) return null;
  return <div style={type==='error' ? css.err : css.ok}>{msg}</div>;
}

function TabBar({ active, onNav }) {
  const tabs = [
    { id:'home',    icon:'🏠', label:'Home' },
    { id:'jobs',    icon:'📄', label:'My Jobs' },
    { id:'shops',   icon:'📍', label:'Shops' },
    { id:'profile', icon:'👤', label:'Profile' },
  ];
  return (
    <div style={css.tabBar}>
      {tabs.map(t => (
        <div key={t.id} style={{ ...css.tabItem, color: active===t.id ? G.green : G.text3 }} onClick={() => onNav(t.id)}>
          <span style={{ fontSize:20 }}>{t.icon}</span>
          <span>{t.label}</span>
        </div>
      ))}
    </div>
  );
}

// ── LOGIN ─────────────────────────────────────────────────────────────────────
function LoginScreen({ onLogin, onGoRegister }) {
  const [phone,    setPhone]    = useState('');
  const [password, setPassword] = useState('');
  const [err,      setErr]      = useState('');
  const [loading,  setLoading]  = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!phone || !password) { setErr('Phone and password are required'); return; }
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/auth/login/', { phone, password });
      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      onLogin(data.user);
    } catch(e) {
      setErr(e.response?.data?.error || 'Login failed');
    } finally { setLoading(false); }
  };

  return (
    <div style={css.center}>
      <div style={css.authWrap}>
        <div style={css.brand}>
          <div style={css.brandIcon}>🖨️</div>
          <div style={css.brandName}>PrintShop</div>
          <div style={{ fontSize:13, color:G.text3, marginTop:6 }}>Print anywhere. Pay once. Collect on the way.</div>
        </div>
        <div style={css.card}>
          <div style={css.formTitle}>Sign in</div>
          <form onSubmit={submit} style={css.col}>
            <div>
              <label style={css.label}>Phone number</label>
              <input style={css.input} placeholder="10-digit mobile" type="tel" maxLength={10}
                value={phone} onChange={e => setPhone(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Password</label>
              <input style={css.input} placeholder="Your password" type="password"
                value={password} onChange={e => setPassword(e.target.value)}/>
            </div>
            <Alert msg={err}/>
            <button type="submit" style={{ ...css.btn, opacity: loading ? 0.6 : 1 }} disabled={loading}>
              {loading ? 'Signing in…' : 'Sign in'}
            </button>
            <div style={css.linkText}>
              No account? <span style={css.link} onClick={onGoRegister}>Sign up</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

// ── REGISTER ──────────────────────────────────────────────────────────────────
function RegisterScreen({ onLogin, onGoLogin }) {
  const [name,     setName]     = useState('');
  const [phone,    setPhone]    = useState('');
  const [password, setPassword] = useState('');
  const [confirm,  setConfirm]  = useState('');
  const [err,      setErr]      = useState('');
  const [loading,  setLoading]  = useState(false);
  const [success,  setSuccess]  = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    if (!name || !phone || !password || !confirm) { setErr('All fields are required'); return; }
    if (password !== confirm)  { setErr('Passwords do not match'); return; }
    if (password.length < 6)   { setErr('Password must be at least 6 characters'); return; }
    if (!/^\d{10}$/.test(phone)) { setErr('Enter a valid 10-digit phone number'); return; }
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/auth/register/', { name, phone, password });
      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      setSuccess(data.user);
    } catch(e) {
      setErr(e.response?.data?.error || 'Registration failed');
    } finally { setLoading(false); }
  };

  if (success) {
    return (
      <div style={css.center}>
        <div style={{ ...css.authWrap, textAlign:'center' }}>
          <div style={css.card}>
            <div style={{ fontSize:48, marginBottom:16 }}>🎉</div>
            <div style={{ fontSize:22, fontWeight:800, color:G.text, marginBottom:8 }}>Account created!</div>
            <div style={{ fontSize:13, color:G.text3, marginBottom:24 }}>Your permanent PrintShop ID</div>
            <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:16, padding:24, marginBottom:16 }}>
              <div style={{ fontSize:11, color:'#4ADE80', marginBottom:8 }}>YOUR ID (show at counter)</div>
              <div style={{ fontSize:56, fontWeight:900, color:G.green, letterSpacing:10 }}>{success.short_id}</div>
              <div style={{ fontSize:14, color:'#4ADE80', marginTop:8 }}>{success.name}</div>
            </div>
            <div style={{ background:'#1A1040', border:`1px solid #2D1A50`, borderRadius:12, padding:16, marginBottom:20 }}>
              <div style={{ fontSize:11, color:'#A78BFA', marginBottom:6 }}>YOUR PICKUP CODE (say at counter)</div>
              <div style={{ fontSize:36, fontWeight:900, color:'#818CF8', letterSpacing:8 }}>{success.pickup_code}</div>
            </div>
            <div style={{ fontSize:12, color:G.text3, marginBottom:20 }}>
              📸 Screenshot this — you'll need the code to collect printouts
            </div>
            <button style={css.btn} onClick={() => onLogin(success)}>Continue to app →</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={css.center}>
      <div style={css.authWrap}>
        <div style={css.brand}>
          <div style={css.brandIcon}>🖨️</div>
          <div style={css.brandName}>PrintShop</div>
        </div>
        <div style={css.card}>
          <div style={css.formTitle}>Create account</div>
          <form onSubmit={submit} style={css.col}>
            <div>
              <label style={css.label}>Full name</label>
              <input style={css.input} placeholder="Your name" value={name} onChange={e => setName(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Phone number</label>
              <input style={css.input} placeholder="10-digit mobile" type="tel" maxLength={10}
                value={phone} onChange={e => setPhone(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Password</label>
              <input style={css.input} placeholder="Min 6 characters" type="password"
                value={password} onChange={e => setPassword(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Confirm password</label>
              <input style={css.input} placeholder="Repeat password" type="password"
                value={confirm} onChange={e => setConfirm(e.target.value)}/>
            </div>
            <Alert msg={err}/>
            <button type="submit" style={{ ...css.btn, opacity: loading ? 0.6 : 1 }} disabled={loading}>
              {loading ? 'Creating account…' : 'Create account'}
            </button>
            <div style={css.linkText}>
              Already have an account? <span style={css.link} onClick={onGoLogin}>Sign in</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

// ── HOME ──────────────────────────────────────────────────────────────────────
function HomeScreen({ user, onNav }) {
  const [jobs, setJobs] = useState([]);
  useEffect(() => {
    api.get('/jobs/').then(r => setJobs(r.data.jobs || [])).catch(() => {});
  }, []);
  const active = jobs.filter(j => !['collected','cancelled','failed'].includes(j.status));

  return (
    <div style={css.page}>
      <div style={{ ...css.card, marginBottom:16, background:'#0D2D1F', border:`1px solid ${G.greenBdr}`, display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <div>
          <div style={{ fontSize:20, fontWeight:800, color:G.text }}>Hello, {user.name.split(' ')[0]} 👋</div>
          <div style={{ fontSize:13, color:'#4ADE80', marginTop:4 }}>
            ID: <strong style={{ letterSpacing:2 }}>{user.short_id}</strong>
          </div>
        </div>
        <button style={{ ...css.btnSm, background:'rgba(255,255,255,0.1)' }} onClick={() => onNav('pickupid')}>
          Show ID
        </button>
      </div>

      <div style={{ background:G.greenDark, borderRadius:16, padding:20, marginBottom:20, display:'flex', alignItems:'center', justifyContent:'space-between', cursor:'pointer', border:`1px solid #166534` }}
        onClick={() => onNav('newjob')}>
        <div style={css.row}>
          <span style={{ fontSize:28 }}>🖨️</span>
          <div>
            <div style={{ fontSize:17, fontWeight:700, color:'#fff' }}>New print job</div>
            <div style={{ fontSize:12, color:'rgba(255,255,255,0.6)', marginTop:2 }}>Upload · Pay · Collect</div>
          </div>
        </div>
        <span style={{ fontSize:22, color:'#4ADE80', fontWeight:700 }}>→</span>
      </div>

      {active.length > 0 && (
        <div style={{ marginBottom:20 }}>
          <span style={css.sectionLabel}>Active jobs</span>
          {active.map(job => {
            const st = STATUS_STYLE[job.status] || STATUS_STYLE.queued;
            return (
              <div key={job.id} style={{ ...css.card, marginBottom:8, display:'flex', alignItems:'center', gap:12, cursor:'pointer' }}
                onClick={() => onNav('jobs')}>
                <span style={{ fontSize:22 }}>📄</span>
                <div style={{ flex:1 }}>
                  <div style={{ fontWeight:600, color:G.text }}>{job.file_name}</div>
                  <div style={{ fontSize:12, color:G.text3, marginTop:2 }}>₹{job.amount}</div>
                </div>
                <span style={{ ...css.badge, background:st.bg, color:st.color }}>{st.label}</span>
              </div>
            );
          })}
        </div>
      )}

      <span style={css.sectionLabel}>Quick actions</span>
      <div style={css.col}>
        {[
          { icon:'📍', title:'Find a shop',    sub:'Shops near you',   color:'#0D2D1F', bdr:'#1A4D30', nav:'shops' },
          { icon:'🪪', title:'My ID card',     sub:'Show at counter',  color:'#1A1040', bdr:'#2D1A50', nav:'pickupid' },
          { icon:'📋', title:'All print jobs', sub:'View history',     color:'#1A1000', bdr:'#2D1A00', nav:'jobs' },
        ].map(a => (
          <div key={a.nav} style={{ background:a.color, border:`1px solid ${a.bdr}`, borderRadius:14, padding:16, display:'flex', alignItems:'center', gap:14, cursor:'pointer' }}
            onClick={() => onNav(a.nav)}>
            <div style={{ width:44, height:44, borderRadius:12, background:'rgba(255,255,255,0.08)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:22 }}>
              {a.icon}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:15, fontWeight:700, color:G.text }}>{a.title}</div>
              <div style={{ fontSize:12, color:G.text3, marginTop:2 }}>{a.sub}</div>
            </div>
            <span style={{ color:G.text3 }}>→</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── JOBS ──────────────────────────────────────────────────────────────────────
function JobsScreen({ onNav }) {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    api.get('/jobs/').then(r => setJobs(r.data.jobs || [])).finally(() => setLoading(false));
  }, []);

  return (
    <div style={css.page}>
      <div style={css.pageTitle}>My Jobs</div>
      {loading ? <Spinner/> : jobs.length === 0 ? (
        <div style={{ textAlign:'center', padding:60, color:G.text3 }}>
          <div style={{ fontSize:48, marginBottom:12 }}>📄</div>
          <div style={{ fontSize:16, fontWeight:600 }}>No jobs yet</div>
          <button style={{ ...css.btn, marginTop:20 }} onClick={() => onNav('newjob')}>+ New print job</button>
        </div>
      ) : jobs.map(job => {
        const st = STATUS_STYLE[job.status] || STATUS_STYLE.queued;
        return (
          <div key={job.id} style={{ ...css.card, marginBottom:8, display:'flex', alignItems:'center', gap:12 }}>
            <div style={{ width:42, height:42, borderRadius:10, background:G.card2, display:'flex', alignItems:'center', justifyContent:'center', fontSize:18 }}>📄</div>
            <div style={{ flex:1 }}>
              <div style={{ fontWeight:600, color:G.text }}>{job.file_name}</div>
              <div style={{ fontSize:12, color:G.text3, marginTop:3 }}>
                ₹{job.amount} · {job.pages}p · {job.color_mode==='bw'?'B&W':'Color'} · {job.copies} {job.copies===1?'copy':'copies'}
              </div>
            </div>
            <span style={{ ...css.badge, background:st.bg, color:st.color }}>{st.label}</span>
          </div>
        );
      })}
    </div>
  );
}

// ── NEW JOB ───────────────────────────────────────────────────────────────────
function NewJobScreen({ onNav }) {
  const [shops,       setShops]       = useState([]);
  const [shopId,      setShopId]      = useState('');
  const [fileName,    setFileName]    = useState('document.pdf');
  const [pages,       setPages]       = useState(1);
  const [colorMode,   setColorMode]   = useState('bw');
  const [paperSize,   setPaperSize]   = useState('A4');
  const [copies,      setCopies]      = useState(1);
  const [doubleSided, setDoubleSided] = useState(false);
  const [amount,      setAmount]      = useState(0);
  const [loading,     setLoading]     = useState(false);
  const [err,         setErr]         = useState('');

  useEffect(() => {
    api.get('/shops/nearby/').then(r => setShops(r.data.shops || [])).catch(() => {});
  }, []);

  useEffect(() => {
    const RATES = { bw: {A4:1.5,A3:2.25,Letter:1.5}, color: {A4:7,A3:10.5,Letter:7} };
    const rate  = (RATES[colorMode] || RATES.bw)[paperSize] || 1.5;
    setAmount(+(rate * pages * copies * (doubleSided ? 0.8 : 1)).toFixed(2));
  }, [pages, colorMode, paperSize, copies, doubleSided]);

  const submit = async () => {
    if (!shopId) { setErr('Please select a shop'); return; }
    setLoading(true); setErr('');
    try {
      await api.post('/jobs/create/', { shop_id:shopId, file_name:fileName, pages, color_mode:colorMode, paper_size:paperSize, copies, double_sided:doubleSided });
      onNav('jobs');
    } catch(e) {
      setErr(e.response?.data?.error || 'Failed to create job');
    } finally { setLoading(false); }
  };

  const chip = (val, cur, set, label) => (
    <button key={val} onClick={() => set(val)}
      style={{ padding:'8px 16px', borderRadius:8, border:`1.5px solid ${cur===val ? G.green : G.border2}`,
        background: cur===val ? G.greenBg : G.card2, color: cur===val ? G.green : G.text2,
        cursor:'pointer', fontWeight:600, fontSize:13 }}>
      {label}
    </button>
  );

  const counter = (val, set, min=1) => (
    <div style={css.row}>
      <button style={{ width:32, height:32, borderRadius:16, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:18 }}
        onClick={() => set(v => Math.max(min, v-1))}>−</button>
      <span style={{ fontSize:18, fontWeight:700, color:G.text, minWidth:32, textAlign:'center' }}>{val}</span>
      <button style={{ width:32, height:32, borderRadius:16, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:18 }}
        onClick={() => set(v => v+1)}>+</button>
    </div>
  );

  return (
    <div style={css.page}>
      <button style={{ background:'none', border:'none', color:G.green, cursor:'pointer', fontSize:14, fontWeight:600, marginBottom:20, padding:0 }} onClick={() => onNav('home')}>← Back</button>
      <div style={css.pageTitle}>New print job</div>
      <div style={css.col}>
        <div style={css.card}>
          <label style={css.label}>Document name</label>
          <input style={css.input} value={fileName} onChange={e => setFileName(e.target.value)} placeholder="e.g. resume.pdf"/>
        </div>

        <div style={css.card}>
          <label style={css.label}>Print shop</label>
          {shops.length === 0 ? (
            <div style={{ color:G.text3, fontSize:13 }}>No shops online right now</div>
          ) : shops.map(s => (
            <div key={s.id} onClick={() => setShopId(s.id)}
              style={{ background: shopId===s.id ? G.greenBg : G.card2, border:`1.5px solid ${shopId===s.id ? G.green : G.border2}`,
                borderRadius:10, padding:12, cursor:'pointer', marginBottom:6 }}>
              <div style={{ fontWeight:700, color:G.text }}>{s.name}</div>
              <div style={{ fontSize:12, color:G.text3, marginTop:2 }}>{s.address}</div>
              <div style={{ fontSize:12, color:G.text3, marginTop:2 }}>Queue: {s.queue_length}/20</div>
              {shopId===s.id && <div style={{ fontSize:12, color:G.green, marginTop:4 }}>✓ Selected</div>}
            </div>
          ))}
        </div>

        <div style={css.card}>
          <label style={css.label}>Preferences</label>
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Color mode</div>
            <div style={css.row}>
              {chip('bw', colorMode, setColorMode, 'Black & White')}
              {chip('color', colorMode, setColorMode, 'Color')}
            </div>
          </div>
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Paper size</div>
            <div style={css.row}>
              {['A4','A3','Letter'].map(s => chip(s, paperSize, setPaperSize, s))}
            </div>
          </div>
          <div style={{ ...css.row, marginBottom:12 }}>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Pages</div>
              {counter(pages, setPages)}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Copies</div>
              {counter(copies, setCopies)}
            </div>
          </div>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:G.card2, padding:12, borderRadius:10 }}>
            <div>
              <div style={{ fontWeight:600, color:G.text, fontSize:14 }}>Double-sided</div>
              <div style={{ fontSize:12, color:G.text3 }}>20% discount</div>
            </div>
            <div onClick={() => setDoubleSided(d => !d)}
              style={{ width:44, height:24, borderRadius:12, background: doubleSided ? G.greenDark : G.card2, border:`1px solid ${doubleSided ? G.green : G.border2}`, position:'relative', cursor:'pointer' }}>
              <div style={{ position:'absolute', top:2, left: doubleSided ? 20 : 2, width:20, height:20, borderRadius:10, background:'#fff', transition:'left 0.2s' }}/>
            </div>
          </div>
        </div>

        <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:14, padding:16, textAlign:'center' }}>
          <div style={{ fontSize:12, color:'#4ADE80', marginBottom:4 }}>Estimated total</div>
          <div style={{ fontSize:36, fontWeight:900, color:G.green }}>₹ {amount}</div>
        </div>

        <Alert msg={err}/>
        <button style={{ ...css.btn, opacity: loading||!shopId ? 0.5 : 1 }}
          onClick={submit} disabled={loading || !shopId}>
          {loading ? 'Creating…' : 'Create job →'}
        </button>
      </div>
    </div>
  );
}

